#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    // If no argument is provided, the original program prints "BALANCED"
    if (argc < 2) {
        puts("BALANCED");
        return 0;
    }

    const char *input = argv[1];
    size_t len = strlen(input);
    // Allocate a stack large enough to hold all opening symbols.
    char *stack = malloc(len + 1);
    if (!stack) return 1; // allocation failure, not expected in original binary
    size_t sp = 0; // stack pointer (number of items on stack)
    int balanced = 1; // assume balanced until a mismatch is found

    for (size_t i = 0; i < len && balanced; ++i) {
        char c = input[i];
        switch (c) {
            case '(':
            case '[':
            case '{':
                // push opening symbol onto the stack
                stack[sp++] = c;
                break;
            case ')':
            case ']':
            case '}': {
                // closing symbol: there must be a matching opening symbol on the stack
                if (sp == 0) {
                    balanced = 0; // nothing to match
                    break;
                }
                char open = stack[--sp];
                if ((c == ')' && open != '(') ||
                    (c == ']' && open != '[') ||
                    (c == '}' && open != '{')) {
                    balanced = 0; // mismatched pair
                }
                break;
            }
            default:
                // any other character is ignored (the original program treats them as neutral)
                break;
        }
    }

    // If there are leftover opening symbols, the string is unbalanced.
    if (sp != 0) balanced = 0;

    puts(balanced ? "BALANCED" : "UNBALANCED");
    free(stack);
    return 0;
}
